<script setup>
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import QuestionFields from '../features/questions/QuestionFields.vue'
import QuestionContent from '../features/questions/QuestionContent.vue'
import ExtractionTasks from '../features/questions/ExtractionTasks.vue'
import { questionTypes, objective } from '../features/questions/types.js'
import MarkdownRenderer from './MarkdownRenderer.vue'
import DocumentManager from './DocumentManager.vue'
import '../personal-bank.css'
const props = defineProps({ workspace: { type: Object, required: true }, documentWorkspace: Object, mode: { type: String, default: '' } })
const w = props.workspace
const emit = defineEmits(['edit-note', 'navigate'])
const uploadOpen = ref(false), resourceQuery = ref(''), resourceType = ref(''), previewPage = ref(1), imageFailed = ref(false)
const role = ref('teaching_material'), links = ref([]), linkStatus = ref('confirmed'), selectedQuestions = ref([]), splitText = ref(''), archiveConfirm = ref(false), wrongOnly = ref(false)
const types = { teaching_material: '教师课件', reference: '教材与参考资料', personal_note: '个人笔记', exercise_material: '习题资料' }
const status = { draft: '待审核草稿', practice: '普通练习', archived: '已归档' }
const answerOrigins = { source_provided: '原资料提供 · 尚未确认', model_inferred: '模型参考 · 尚未确认', human_confirmed: '人工确认答案', unknown: '无可靠答案' }
const visibleResources = computed(() => w.resources.filter(r => r.status === 'active' && (!resourceType.value || r.resource_type === resourceType.value) && r.title.includes(resourceQuery.value)))
const concepts = computed(() => w.knowledge.flatMap(g => g.concepts.map(c => ({ ...c, architecture_id: g.architecture_id, label: `${g.name} / ${c.name}` }))))
const chapters = computed(() => w.knowledge.flatMap(g => g.chapters.map(c => ({ ...c, architecture_id: g.architecture_id, label: `${g.name} / ${c.title}` }))))
const source = computed(() => w.section === 'bank' ? w.current?.source : w.section === 'practice' ? w.session?.source : w.resource)
const sourceImage = computed(() => w.preview(source.value, previewPage.value))
const sourceSnapshot = computed(() => source.value?.evidence || (w.section === 'resources' ? w.sourceUnits.map(u => ({ ...u, raw_md: u.text })) : []))
const recoveries = computed(() => Object.entries(w.drafts).filter(([key, value]) => key.startsWith('recovery-') && value.payload))
watch(() => w.resource, r => { role.value = r?.resource_type || 'teaching_material'; links.value = JSON.parse(JSON.stringify(r?.links || [])) })
watch(source, s => { previewPage.value = s?.evidence?.[0]?.location?.page_number || 1; imageFailed.value = false; archiveConfirm.value = false })
watch(previewPage, () => { imageFailed.value = false })
onMounted(async () => { w.visible = true; await w.load(); if (props.mode === 'resources') w.section = 'resources'; else if (props.mode === 'bank' && w.section === 'resources') w.section = 'bank' })
watch(() => w.section, value => { if (props.mode === 'resources' && value !== 'resources') emit('navigate', 'bank', { question: w.current?.id, view: value }); else if (props.mode === 'bank' && value === 'resources') emit('navigate', 'materials', { resource: w.resource?.resource_id }) })
onUnmounted(() => { w.persist(); w.visible = false })
function changeType() {
  w.editor.answer = null
  if (w.editor.question_type === 'true_false') w.editor.options = [{ key: 'true', text: '正确' }, { key: 'false', text: '错误' }]
  else if (!w.editor.options.length || w.editor.options[0].key === 'true') w.editor.options = [{ key: 'A', text: '' }, { key: 'B', text: '' }]
}
function toggleConcept(c, checked) {
  w.editor.concepts = checked ? [...w.editor.concepts, { architecture_id: c.architecture_id, concept_id: c.id }] : w.editor.concepts.filter(r => !(r.architecture_id === c.architecture_id && r.concept_id === c.id))
}
function toggleLink(c, kind, checked) {
  links.value = links.value.filter(r => !(r.architecture_id === c.architecture_id && r.node_id === c.id && r.kind === kind))
  if (checked) links.value.push({ architecture_id: c.architecture_id, node_id: c.id, kind, review_status: linkStatus.value })
}
function merge() {
  const rows = w.questions.filter(r => selectedQuestions.value.includes(r.id) && r.status !== 'archived')
  if (rows.length < 2) return
  w.restructure(rows.map(r => ({ question_id: r.id, expected_revision: r.revision })), [{ stem: rows.map(r => r.payload.stem).join('\n\n'), question_type: 'other', options: [], answer: null, explanation: '', concepts: [] }])
}
function split() {
  const parts = splitText.value.split(/\n---\n/).map(s => s.trim()).filter(Boolean)
  if (parts.length < 2) { w.error = '请用单独一行 --- 分隔至少两个题干。'; return }
  w.restructure([{ question_id: w.current.id, expected_revision: w.current.revision }], parts.map(stem => ({ stem, question_type: 'other', options: [], answer: null, explanation: '', concepts: w.editor.concepts })))
}
function originalUrl(s) {
  if (s?.original_source_type !== 'document') return null
  return `/api/v1/students/${encodeURIComponent(w.owner)}/documents/${s.original_source_id}/original?version_id=${encodeURIComponent(s.source_version)}`
}
</script>

<template>
  <section class="pb-workspace" aria-label="课程资源与个人题库">
    <header class="panel pb-heading"><div><h2>{{ mode === 'resources' ? '课程资料' : '我的题库' }}</h2><p>同一份资料复用解析，经人工审核后进入普通练习。普通练习不更新BKT或正式学习记录。</p></div><button class="button secondary" :disabled="Boolean(w.busy)" @click="w.load()">只读刷新</button></header>
    <nav v-if="mode !== 'resources'" class="doc-switch" aria-label="个人题库步骤"><button v-for="[key,label] in [['bank','提取与审核'],['practice','普通练习与历史']]" :key="key" class="button secondary" :aria-pressed="w.section === key" @click="w.section = key">{{ label }}</button></nav>
    <p v-if="w.error" class="alert alert-error" role="alert">{{ w.error }}</p><p v-if="w.notice" class="alert alert-info" role="status">{{ w.notice }}</p>
    <div v-if="w.pending" class="panel" role="status"><p>原操作待核对，不会自动重新导入或提交。</p><details><summary>技术详情</summary>{{ w.pending.request_id }}</details><button class="button secondary" @click="w.load()">查询原回执</button><button class="button secondary" @click="w.releasePending()">保留编号并结束等待</button></div>
    <p v-if="w.busy" role="status">正在处理，请稍候…</p>
    <section v-if="w.section === 'resources'" class="panel pb-form"><label for="pb-extraction-mode">原题识别方式</label><select id="pb-extraction-mode" v-model="w.extractionMode"><option value="model">Agent语义提取 · DeepSeek</option><option value="local">本地规则 · 不外发</option></select><template v-if="w.extractionMode === 'model'"><p>发送本轮所选资料的完整原文；若勾选原页图，同时发送选中页图片。最多3个相邻页、每次10000输出token、最多2次调用（含一次结构复核）。不解题、不自动覆盖已审核题目。</p><label class="pb-check"><input v-model="w.includeImages" type="checkbox" />同时使用原页图（PDF/图片，用于公式、表格和复杂版面）</label><label class="pb-check"><input v-model="w.extractionConsent" type="checkbox" />我有权使用并同意仅本轮将所选原文/页图发送至DeepSeek</label></template></section>
    <template v-if="w.section === 'resources'">
      <section class="panel"><button v-if="documentWorkspace" class="button secondary" :aria-expanded="uploadOpen" @click="uploadOpen = !uploadOpen; if (!uploadOpen) w.load()">{{ uploadOpen ? '收起解析管理并刷新目录' : '上传文件 / 图片，查看解析与版本' }}</button><p class="small muted">复用原有上传管理。图片本地仅登记尺寸和原件；视觉转录需本轮外发同意并计费，真实识别质量尚未实测。教师课件尚未接入RAG，已具备RAG的笔记与课程资料共享原文，无需重复上传。</p></section>
      <DocumentManager v-if="uploadOpen && documentWorkspace" :workspace="documentWorkspace" />
      <div class="pb-grid">
        <aside class="panel pb-list"><h3>课程资源</h3><label for="pb-resource-search">标题搜索</label><input id="pb-resource-search" v-model="resourceQuery" /><label for="pb-resource-type">资源类型</label><select id="pb-resource-type" v-model="resourceType"><option value="">全部类型</option><option v-for="(label,key) in types" :key="key" :value="key">{{ label }}</option></select>
          <button v-for="r in visibleResources" :key="r.resource_id" class="pb-item" :disabled="Boolean(w.busy)" :aria-pressed="w.resource?.resource_id === r.resource_id" @click="w.selectResource(r)"><strong>{{ r.title }}</strong><small>{{ types[r.resource_type] }} · {{ r.format }} · 解析 {{ r.parse_status }}</small><small>{{ r.rag_available ? '已有RAG能力' : '未接入RAG' }}</small></button>
        </aside>
        <section v-if="w.resource" class="panel pb-detail"><h3>{{ w.resource.title }}</h3><button class="button secondary" @click="emit('navigate','bank',{resource:w.resource.resource_id})">查看这份资料的题目</button><details><summary>技术详情</summary><p>资源ID {{ w.resource.resource_id }} · 修订 {{ w.resource.revision }} · 来源版本 {{ w.resource.source_version }}</p></details>
          <a v-if="originalUrl(source)" class="button secondary" :href="originalUrl(source)">下载同一原件</a><button v-if="w.resource.original_source_type === 'personal_note'" class="button secondary" @click="emit('edit-note',w.resource.original_source_id)">打开笔记编辑器</button>
          <form class="pb-form" @submit.prevent="w.extractResource()"><label for="pb-run">复用已保存解析（不重复调用模型）</label><select id="pb-run" :value="w.runId" :disabled="!w.resource.parse_id || Boolean(w.busy)" @change="w.selectRun($event.target.value)"><option v-if="!w.parseRuns.length" value="">当前原文</option><option v-for="r in w.parseRuns" :key="r.id" :value="r.id">{{ r.mode==='vision' ? '已保存视觉转录 · 待核对' : '本地解析' }} · {{ r.status }} · {{ r.created_at }}</option></select><label for="pb-extract-pages">限定页 / 幻灯片编号，逗号分隔；留空使用该解析全部单位</label><input id="pb-extract-pages" v-model="w.ordinals" :disabled="!w.resource.parse_id" placeholder="1,2" /><button class="button primary" :disabled="Boolean(w.busy || w.pending)">从这份资料提取原有习题</button><p class="small muted">不会重复上传或重新解析，不会创造新题或补猜缺失答案。</p></form>
          <details><summary>资源类型与知识关联</summary><label for="pb-role">资源用途</label><select id="pb-role" v-model="role"><option v-for="(label,key) in types" :key="key" :value="key">{{ label }}</option></select><label for="pb-link-status">新增关联状态</label><select id="pb-link-status" v-model="linkStatus"><option value="candidate">候选关联</option><option value="confirmed">我已确认</option></select>
            <fieldset><legend>已发布章节和概念（可多选）</legend><label v-for="c in chapters" :key="c.id" class="pb-check"><input type="checkbox" :checked="links.some(r=>r.node_id===c.id && r.architecture_id===c.architecture_id)" @change="toggleLink(c,'chapter',$event.target.checked)" />章节：{{ c.label }}</label><label v-for="c in concepts" :key="c.id" class="pb-check"><input type="checkbox" :checked="links.some(r=>r.node_id===c.id && r.architecture_id===c.architecture_id)" @change="toggleLink(c,'concept',$event.target.checked)" />概念：{{ c.label }}</label><p v-if="!concepts.length && !chapters.length">暂无已发布结构，请先在课程知识体系确认发布。</p></fieldset>
            <ul><li v-for="link in links" :key="link.node_id">{{ link.kind }} · {{ link.review_status === 'confirmed' ? '人工确认' : '候选' }} · {{ link.node_id }}</li></ul><button class="button secondary" :disabled="Boolean(w.busy || w.pending)" @click="w.saveLinks({expected_revision:w.resource.revision,resource_type:role,links})">保存资源关联</button></details>
          <div v-if="sourceImage" class="pb-original"><label for="pb-resource-page">原件预览页</label><input id="pb-resource-page" v-model.number="previewPage" type="number" min="1" max="200" /><img v-if="!imageFailed" :src="sourceImage" alt="当前资料的原始页或图片预览" @error="imageFailed=true" /><p v-else role="status">本页预览不可用，请下载原件或查看已保存文本。</p></div>
          <details><summary>查看复用的解析文本</summary><article v-for="u in w.sourceUnits" :key="u.id"><p class="small">{{ JSON.stringify(u.location) }}</p><MarkdownRenderer :source="u.text" /></article></details>
        </section><section v-else class="panel"><p>选择一份资料，查看原文并直接提取。</p></section>
      </div>
      <section class="panel pb-form"><h3>粘贴已有习题</h3><label for="pb-paste">原题文字（最多60000字符，保留原题答案行，例如“答案：A”）</label><textarea id="pb-paste" v-model="w.paste" rows="6" maxlength="60000" /><button class="button primary" :disabled="Boolean(w.busy || w.pending || !w.paste.trim())" @click="w.extractText()">提取为待审核草稿</button><button class="button secondary" @click="w.newQuestion()">手工录入一道题</button></section>
    </template>
    <template v-else-if="w.section === 'bank'">
      <ExtractionTasks :workspace="w" />
      <section class="panel pb-filters"><label>搜索题干<input v-model="w.filter.q" maxlength="200" /></label><label>状态<select v-model="w.filter.status"><option value="">全部</option><option v-for="(label,key) in status" :key="key" :value="key">{{ label }}</option></select></label><label>题型<select v-model="w.filter.question_type"><option value="">全部</option><option v-for="(label,key) in questionTypes" :key="key" :value="key">{{ label }}</option></select></label><label>来源<select v-model="w.filter.resource_id"><option value="">全部来源</option><option v-for="r in w.resources" :key="r.resource_id" :value="r.resource_id">{{ r.title }}</option></select></label><label>章节<select v-model="w.filter.chapter_id"><option value="">全部章节</option><option v-for="c in chapters" :key="c.id" :value="c.id">{{ c.label }}</option></select></label><label>概念<select v-model="w.filter.concept_id"><option value="">全部概念</option><option v-for="c in concepts" :key="c.id" :value="c.id">{{ c.label }}</option></select></label><button class="button secondary" :disabled="Boolean(w.busy)" @click="w.load()">应用筛选</button><button class="button secondary" @click="w.newQuestion()">手工新建</button></section>
      <div class="pb-grid pb-review-grid"><aside class="panel pb-list"><h3>个人题库 · {{ w.questions.length }}题</h3><div v-for="q in w.questions" :key="q.id" class="pb-question-row"><label class="pb-check"><input v-model="selectedQuestions" type="checkbox" :value="q.id" :disabled="q.status === 'archived'" :aria-label="`选择合并：${q.payload.stem.slice(0,30)}`" /></label><button class="pb-item" :aria-pressed="w.current?.id===q.id" @click="w.open(q.id)"><strong>{{ q.payload.stem.slice(0,70) }}</strong><small>{{ status[q.status] }} · r{{ q.revision }} · {{ q.source_status }}</small><small v-if="q.duplicate_ids.length">疑似重复，请人工核对</small></button></div><button class="button secondary" :disabled="Boolean(w.busy || w.pending || selectedQuestions.length<2)" @click="merge">合并勾选题为新草稿</button></aside>
        <section class="panel pb-review"><div class="pb-actions"><h3>{{ w.current ? '题目审核' : '手工录题' }}</h3><button v-if="w.current?.source.resource_id" class="button secondary" @click="emit('navigate','materials',{resource:w.current.source.resource_id})">打开来源资料</button><span role="status">{{ w.dirty ? '有本机未保存草稿' : '已与服务器同步' }}</span><span v-if="w.current">r{{ w.current.revision }} · {{ status[w.current.status] }}</span></div>
          <p v-if="w.current" class="small muted">答案：{{ answerOrigins[w.current.answer_provenance] }} · 来源：{{ w.current.source_status }}。软删除和归档保留历史，不是物理清除。</p>
          <p v-if="w.conflict" class="alert alert-error">服务器版本已变化。请保留恢复副本后读取服务器版本，再手动合并。</p><button v-if="w.conflict" class="button secondary" @click="w.keepConflictCopy()">保留冲突副本并读取服务器版本</button>
          <button v-for="[key] in recoveries" :key="key" class="button secondary" @click="w.restoreCopy(key)">恢复草稿副本 {{ key.slice(-13) }}</button>
          <section v-if="w.proposalOriginal" class="panel"><h4>修正稿与原题对照</h4><p>接受后保存为原题的新草稿版本；历史保持，需重新审核。{{ w.proposalOriginal.revision !== w.current.source.proposal_for.revision ? '原题已有其他修改，不能直接接受。' : '' }}</p><div class="pb-editor-grid"><div><h4>原题</h4><QuestionContent :value="w.proposalOriginal.payload" /></div><div><h4>本次修正</h4><QuestionContent :value="w.editor" /></div></div><button class="button primary" :disabled="Boolean(w.dirty || w.busy || w.pending || w.proposalOriginal.revision !== w.current.source.proposal_for.revision)" @click="w.acceptProposal()">接受修正为原题新草稿</button><button class="button secondary" @click="w.open(w.proposalOriginal.id)">保留原稿并返回</button></section>
          <div class="pb-editor-grid"><aside class="pb-original"><h4>原始位置与快照</h4><a v-if="originalUrl(source)" :href="originalUrl(source)">下载当时版本原件</a><label v-if="sourceImage" for="pb-review-page">查看原件页码</label><input v-if="sourceImage" id="pb-review-page" v-model.number="previewPage" type="number" min="1" max="200" /><img v-if="sourceImage && !imageFailed" :src="sourceImage" alt="题目来源原始页面或图片" @error="imageFailed=true" /><p v-if="imageFailed" role="status">原件预览失败，保留的文本快照仍可查看。</p><article v-for="(e,index) in sourceSnapshot" :key="index"><p class="small">{{ JSON.stringify(e.location) }} · {{ e.origin }}</p><MarkdownRenderer :source="e.raw_md" /><p v-if="e.warnings?.length" class="small muted">提取提示：{{ e.warnings.join('，') }}</p></article><p v-if="!sourceSnapshot.length">手工题没有文件来源。</p><p v-if="w.current?.source.warnings?.length" class="wb-run-notice">需核对：{{ w.current.source.warnings.join('，') }}</p><p v-if="w.current?.source.candidate_concepts?.length" class="small">规则候选概念（尚未确认）：{{ w.current.source.candidate_concepts.map(c=>c.name).join('、') }}</p></aside>
            <form class="pb-form" @submit.prevent="w.save('draft')"><fieldset :disabled="Boolean(w.busy || w.pending)"><legend>编辑原题</legend><QuestionFields :value="w.editor" /><fieldset><legend>关联已发布知识概念（可多选，不进入BKT）</legend><label v-for="c in concepts" :key="c.id" class="pb-check"><input type="checkbox" :checked="w.editor.concepts.some(r=>r.architecture_id===c.architecture_id && r.concept_id===c.id)" @change="toggleConcept(c,$event.target.checked)" />{{ c.label }}</label><p v-if="!concepts.length">暂无已发布概念，题目可以先保存。</p></fieldset>
              <label class="pb-check"><input v-model="w.reviewed" type="checkbox" />我已人工核对题干、选项及资料还原结果。</label><label class="pb-check"><input v-model="w.confirmAnswer" type="checkbox" :disabled="!w.editor.answer && !w.editor.answer_text && !w.editor.answer_keys?.length" />我已核对参考答案（仅单选/判断可用作客观评分依据）。</label><label v-if="w.current && !['current','manual'].includes(w.current.source_status)" class="pb-check"><input v-model="w.acknowledge" type="checkbox" />我已核对来源变化，明确使用保留的题目快照。</label>
              <div class="pb-actions"><button class="button secondary" :disabled="w.conflict">保存草稿</button><button type="button" class="button primary" :disabled="Boolean(w.conflict || !w.reviewed || ['other','unknown'].includes(w.editor.question_type))" @click="w.save('practice')">确认进入普通练习</button></div><p class="small muted">未人工确认答案时可以练习，但不会给出客观分数。修改后需重新审核；不修改正式题库。</p>
            </fieldset></form>
          </div>
          <section v-if="w.current?.source.resource_id" class="panel"><h4>局部重识别</h4><p>读取本题来源页，产生新的修正草稿供对照；原题不被覆盖。</p><label class="pb-check"><input v-model="w.extractionConsent" type="checkbox" />同意本轮发送本题来源原文/原页至DeepSeek</label><label class="pb-check"><input v-model="w.includeImages" type="checkbox" />同时使用原页图（仅PDF/图片）</label><button class="button secondary" :disabled="Boolean(w.busy || w.pending || !w.extractionConsent || w.dirty)" @click="w.reextract()">生成修正草稿</button></section>
          <details><summary>题目实时预览</summary><QuestionContent :value="w.editor" /><div v-for="o in w.editor.options" :key="o.key"><strong>{{ o.key }}</strong><MarkdownRenderer :source="o.text" /></div><MarkdownRenderer :source="w.editor.explanation" /></details>
          <div v-if="w.current" class="pb-actions"><button class="button primary" :disabled="Boolean(w.busy || w.pending || w.current.status!=='practice' || w.dirty)" @click="w.start(w.current.id)">开始这道普通练习</button><button class="button secondary" @click="w.history()">查看审核历史</button><label class="pb-check"><input v-model="archiveConfirm" type="checkbox" />确认归档</label><button class="button secondary" :disabled="Boolean(w.busy || w.pending || !archiveConfirm || w.current.status==='archived')" @click="w.archive()">归档题目</button></div>
          <details v-if="w.current"><summary>拆分当前题为多个草稿</summary><label for="pb-split">每段为一道题干，用独立一行 --- 分隔。拆分后的选项、答案需重新补充审核。</label><textarea id="pb-split" v-model="splitText" rows="5" /><button class="button secondary" :disabled="Boolean(w.busy || w.pending || w.dirty || w.current.status==='archived')" @click="split">确认拆分并归档原题</button></details>
          <details v-for="revision in w.revisions" :key="revision.revision"><summary>审核历史 r{{ revision.revision }} · {{ status[revision.status] }} · {{ revision.created_at }}</summary><MarkdownRenderer :source="revision.payload.stem" /><p>{{ revision.review.answer_confirmed ? '人工确认答案' : '答案尚未确认' }}</p></details>
        </section>
      </div>
    </template>
    <template v-else>
      <div class="pb-grid"><section class="panel"><h3>普通练习</h3><p class="small muted">与正式诊断独立，不修改掌握度、正式作答或学情版本。每次开始选择一道已审核题，可重复练习。</p><label for="pb-practice-concept">知识概念</label><select id="pb-practice-concept" v-model="w.filter.concept_id"><option value="">整个当前课程</option><option v-for="c in concepts" :key="c.id" :value="c.id">{{ c.label }}</option></select><label class="pb-check"><input v-model="w.acknowledge" type="checkbox" />如来源已变化，我明确选择使用已审核题目快照。</label><button class="button primary" :disabled="Boolean(w.busy || w.pending)" @click="w.start()">开始下一道普通练习</button>
          <article v-if="w.session" class="pb-session"><p class="small muted">题目r{{ w.session.question_revision }} · {{ w.session.source.title || '手工录题' }} · 来源{{ w.session.source_status }}</p><QuestionContent :value="w.session.question" /><form @submit.prevent="w.submit()"><fieldset :disabled="Boolean(w.busy || w.pending || w.session.result)"><legend>{{ objective(w.session.question) ? '选择答案' : '文字作答（不自动判分）' }}</legend><label v-for="o in objective(w.session.question) ? w.session.question.options : []" :key="o.key" class="pb-check pb-choice"><input v-model="w.selected" type="radio" name="personal-answer" :value="o.key" /><strong>{{ o.key }}</strong><MarkdownRenderer :source="o.text" /></label><template v-if="!objective(w.session.question)"><div v-for="o in w.session.question.options" :key="o.key"><strong>{{ o.key }}</strong><MarkdownRenderer :source="o.text" /></div><label for="pb-response">我的作答 Markdown / LaTeX</label><textarea id="pb-response" v-model="w.selected" rows="8" maxlength="16000" /><label class="pb-check"><input v-model="w.needsReview" type="checkbox" />自行标记需要复习（主观标记，不算客观错题）</label><button type="button" class="button secondary" @click="w.saveResponseDraft()">保存文字作答草稿</button></template><button v-if="!w.session.result" class="button primary" :disabled="!w.selected">提交普通练习</button></fieldset></form>
            <section v-if="w.session.result" role="status"><h4>{{ w.session.result.correct === null ? '本题仅保存作答，不进行客观判分' : w.session.result.correct ? '回答正确' : '回答错误' }}</h4><p v-if="w.session.result.correct!==null">已确认答案 {{ w.session.result.correct_answer }} · 分数 {{ w.session.result.score }}/1</p><div v-if="w.session.result.reference_answer"><p>参考答案（来源标记以题目审核记录为准，不作主观题评分依据）</p><MarkdownRenderer :source="String(w.session.result.reference_answer)" /></div><p v-if="w.session.result.needs_review">已自行标记需复习，不计入客观错题。</p><MarkdownRenderer :source="w.session.result.explanation" /><button class="button secondary" :disabled="Boolean(w.busy || w.pending)" @click="w.start(w.session.question_id)">再次练习本题</button></section>
            <details><summary>本轮来源快照</summary><MarkdownRenderer v-for="(e,index) in w.session.source.evidence || []" :key="index" :source="e.raw_md" /></details>
          </article>
        </section><aside class="panel pb-list"><h3>普通练习历史</h3><p class="small muted">最近100次。历史保存实际题目版本和评分依据；刷新只读恢复。</p><label class="pb-check"><input v-model="wrongOnly" type="checkbox" />仅看错题</label><button v-for="item in w.sessions.filter(s=>!wrongOnly || s.result?.correct===false)" :key="item.id" class="pb-item" @click="w.viewSession(item)"><strong>{{ item.question.stem.slice(0,70) }}</strong><small>{{ item.result ? item.result.correct===null ? '未判分' : item.result.correct ? '答对' : '错题' : '等待作答' }} · r{{ item.question_revision }} · {{ item.created_at }}</small></button></aside></div>
    </template>
  </section>
</template>
